        }
        leaf out-errors {
          type uint32;
          config false;
          status deprecated;
          description
            "For packet-oriented interfaces, the number of outbound
             packets that could not be transmitted because of errors.
             For character-oriented or fixed-length interfaces, the
             number of outbound transmission units that could not be
             transmitted because of errors.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifOutErrors";
        }
      }
      container ipv4 {
        presence "true";
        config false;
        status deprecated;
        description
          "Interface-specific parameters for the IPv4 address family.";
        leaf forwarding {
          type boolean;
          config false;
          status deprecated;
          description
            "Indicates whether IPv4 packet forwarding is enabled or
             disabled on this interface.";
        }
        leaf mtu {
          type uint16 {
            range "68..65535";
          }
          units "octets";
          config false;
          status deprecated;
          description
            "The size, in octets, of the largest IPv4 packet that the
             interface will send and receive.";
          reference
            "RFC 791: Internet Protocol";
        }
        list address {
          key "ip";
          config false;
          min-elements 0;
          max-elements 4294967295;
          ordered-by user;
          status deprecated;
          description
            "The list of IPv4 addresses on the interface.";
          leaf ip {
            type string {
              pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
              pattern "[0-9\\.]*";
            }
            config false;
            status deprecated;
            description
              "The IPv4 address on the interface.";
          }
          choice subnet {
            config false;
            status deprecated;
            description
              "The subnet can be specified as a prefix length or,
               if the server supports non-contiguous netmasks, as
               a netmask.";
            case prefix-length {
              config false;
              status deprecated;
              leaf prefix-length {
                type uint8 {
                  range "0..32";
                }
                config false;
                status deprecated;
                description
                  "The length of the subnet prefix.";
              }
            }
            case netmask {
              config false;
              status deprecated;
              leaf netmask {
                type string {
                  pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                }
                config false;
                status deprecated;
                description
                  "The subnet specified as a netmask.";
              }
            }
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the address has been statically
                   configured -- for example, using the Network Configuration
                   Protocol (NETCONF) or a command line interface.";
              }
              enum "dhcp" {
                value 2;
                status current;
                description
                  "Indicates an address that has been assigned to this
                   system by a DHCP server.";
              }
              enum "link-layer" {
                value 3;
                status current;
                description
                  "Indicates an address created by IPv6 stateless
                   autoconfiguration that embeds a link-layer address in its
                   interface identifier.";
              }
              enum "random" {
                value 4;
                status current;
                description
                  "Indicates an address chosen by the system at
                   random, e.g., an IPv4 address within 169.254/16, a
                   temporary address as described in RFC 4941, or a
                   semantically opaque address as described in RFC 7217.";
                reference
                  "RFC 4941: Privacy Extensions for Stateless Address
                             Autoconfiguration in IPv6
                   RFC 7217: A Method for Generating Semantically Opaque
                             Interface Identifiers with IPv6 Stateless
                             Address Autoconfiguration (SLAAC)";
              }
            }
            config false;
            status deprecated;
            description
              "The origin of this address.";
          }
        }
        list neighbor {
          key "ip";
          config false;
          min-elements 0;
          max-elements 4294967295;
          ordered-by user;
          status deprecated;
          description
            "A list of mappings from IPv4 addresses to
             link-layer addresses.

             This list represents the ARP Cache.";
          reference
            "RFC 826: An Ethernet Address Resolution Protocol";
          leaf ip {
            type string {
              pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
              pattern "[0-9\\.]*";
            }
            config false;
            status deprecated;
            description
              "The IPv4 address of the neighbor node.";
          }
          leaf link-layer-address {
            type string {
              pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
            }
            config false;
            status deprecated;
            description
              "The link-layer address of the neighbor node.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the mapping has been statically
                   configured -- for example, using NETCONF or a command line
                   interface.";
              }
              enum "dynamic" {
                value 2;
                status current;
                description
                  "Indicates that the mapping has been dynamically resolved
                   using, for example, IPv4 ARP or the IPv6 Neighbor
                   Discovery protocol.";
              }
            }
            config false;
            status deprecated;
            description
              "The origin of this neighbor entry.";
          }
        }
      }
      container ipv6 {
        presence "true";
        config false;
        status deprecated;
        description
          "Parameters for the IPv6 address family.";
        leaf forwarding {
          type boolean;
          default "false";
          config false;
          status deprecated;
          description
            "Indicates whether IPv6 packet forwarding is enabled or
             disabled on this interface.";
          reference
            "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                       Section 6.2.1, IsRouter";
        }
        leaf mtu {
          type uint32 {
            range "1280..4294967295";
          }
          units "octets";
          config false;
          status deprecated;
          description
            "The size, in octets, of the largest IPv6 packet that the
             interface will send and receive.";
          reference
            "RFC 8200: Internet Protocol, Version 6 (IPv6)
                       Specification
                       Section 5";
        }
        list address {
          key "ip";
          config false;
          min-elements 0;
          max-elements 4294967295;
          ordered-by user;
          status deprecated;
          description
            "The list of IPv6 addresses on the interface.";
          leaf ip {
            type string {
              pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
              pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              pattern "[0-9a-fA-F:\\.]*";
            }
            config false;
            status deprecated;
            description
              "The IPv6 address on the interface.";
          }
          leaf prefix-length {
            type uint8 {
              range "0..128";
            }
            config false;
            mandatory true;
            status deprecated;
            description
              "The length of the subnet prefix.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the address has been statically
                   configured -- for example, using the Network Configuration
                   Protocol (NETCONF) or a command line interface.";
              }
              enum "dhcp" {
                value 2;
                status current;
                description
                  "Indicates an address that has been assigned to this
                   system by a DHCP server.";
              }
              enum "link-layer" {
                value 3;
                status current;
                description
                  "Indicates an address created by IPv6 stateless
                   autoconfiguration that embeds a link-layer address in its
                   interface identifier.";
              }
              enum "random" {
                value 4;
                status current;
                description
                  "Indicates an address chosen by the system at
                   random, e.g., an IPv4 address within 169.254/16, a
                   temporary address as described in RFC 4941, or a
                   semantically opaque address as described in RFC 7217.";
                reference
                  "RFC 4941: Privacy Extensions for Stateless Address
                             Autoconfiguration in IPv6
                   RFC 7217: A Method for Generating Semantically Opaque
                             Interface Identifiers with IPv6 Stateless
                             Address Autoconfiguration (SLAAC)";
              }
            }
            config false;
            status deprecated;
            description
              "The origin of this address.";
          }
          leaf status {
            type enumeration {
              enum "preferred" {
                value 0;
                status current;
                description
                  "This is a valid address that can appear as the
                   destination or source address of a packet.";
              }
              enum "deprecated" {
                value 1;
                status current;
                description
                  "This is a valid but deprecated address that should
                   no longer be used as a source address in new
                   communications, but packets addressed to such an
                   address are processed as expected.";
              }
              enum "invalid" {
                value 2;
                status current;
                description
                  "This isn't a valid address, and it shouldn't appear
                   as the destination or source address of a packet.";
              }
              enum "inaccessible" {
                value 3;
                status current;
                description
                  "The address is not accessible because the interface
                   to which this address is assigned is not
                   operational.";
              }
              enum "unknown" {
                value 4;
                status current;
                description
                  "The status cannot be determined for some reason.";
              }
              enum "tentative" {
                value 5;
                status current;
                description
                  "The uniqueness of the address on the link is being
                   verified.  Addresses in this state should not be
                   used for general communication and should only be
                   used to determine the uniqueness of the address.";
              }
              enum "duplicate" {
                value 6;
                status current;
                description
                  "The address has been determined to be non-unique on
                   the link and so must not be used.";
              }
              enum "optimistic" {
                value 7;
                status current;
                description
                  "The address is available for use, subject to
                   restrictions, while its uniqueness on a link is
                   being verified.";
              }
            }
            config false;
            status deprecated;
            description
              "The status of an address.  Most of the states correspond
               to states from the IPv6 Stateless Address
               Autoconfiguration protocol.";
            reference
              "RFC 4293: Management Information Base for the
                         Internet Protocol (IP)
                         - IpAddressStatusTC
               RFC 4862: IPv6 Stateless Address Autoconfiguration";
          }
        }
        list neighbor {
          key "ip";
          config false;
          min-elements 0;
          max-elements 4294967295;
          ordered-by user;
          status deprecated;
          description
            "A list of mappings from IPv6 addresses to
             link-layer addresses.

             This list represents the Neighbor Cache.";
          reference
            "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)";
          leaf ip {
            type string {
              pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
              pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              pattern "[0-9a-fA-F:\\.]*";
            }
            config false;
            status deprecated;
            description
              "The IPv6 address of the neighbor node.";
          }
          leaf link-layer-address {
            type string {
              pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
            }
            config false;
            status deprecated;
            description
              "The link-layer address of the neighbor node.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the mapping has been statically
                   configured -- for example, using NETCONF or a command line
                   interface.";
              }
              enum "dynamic" {
                value 2;
                status current;
                description
                  "Indicates that the mapping has been dynamically resolved
                   using, for example, IPv4 ARP or the IPv6 Neighbor
                   Discovery protocol.";
              }
            }
            config false;
            status deprecated;
            description
              "The origin of this neighbor entry.";
          }
          leaf is-router {
            type empty;
            config false;
            status deprecated;
            description
              "Indicates that the neighbor node acts as a router.";
          }
          leaf state {
            type enumeration {
              enum "incomplete" {
                value 0;
                status current;
                description
                  "Address resolution is in progress, and the
                   link-layer address of the neighbor has not yet been
                   determined.";
              }
              enum "reachable" {
                value 1;
                status current;
                description
                  "Roughly speaking, the neighbor is known to have been
                   reachable recently (within tens of seconds ago).";
              }
              enum "stale" {
                value 2;
                status current;
                description
                  "The neighbor is no longer known to be reachable, but
                   until traffic is sent to the neighbor no attempt
                   should be made to verify its reachability.";
              }
              enum "delay" {
                value 3;
                status current;
                description
                  "The neighbor is no longer known to be reachable, and
                   traffic has recently been sent to the neighbor.
                   Rather than probe the neighbor immediately, however,
                   delay sending probes for a short while in order to
                   give upper-layer protocols a chance to provide
                   reachability confirmation.";
              }
              enum "probe" {
                value 4;
                status current;
                description
                  "The neighbor is no longer known to be reachable, and
                   unicast Neighbor Solicitation probes are being sent
                   to verify reachability.";
              }
            }
            config false;
            status deprecated;
            description
              "The Neighbor Unreachability Detection state of this
               entry.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         Section 7.3.2";
          }
        }
      }
    }
  }
